+constexpr static std::initializer_list<std::pair<NodeType, NodeType>>
+    kNodeTypeExclusivePairs{
+        {NodeType::kAnyHeapObject, NodeType::kSmi},
+        {NodeType::kNumberOrOddball, NodeType::kName},
