+inline constexpr bool NodeTypeCannotHaveInstances(NodeType type) {
+  for (auto types : kNodeTypeExclusivePairs) {
+    if (NodeTypeIs(type, types.first) && NodeTypeIs(type, types.second)) {
+      return true;
+    }
+  }
